/**
 * Synthetic answers of the two research tools (data-quality report, FAERS onset table) for the
 * behaviour tests. Typed with the production types and decoded by the production decoders; nothing
 * is read from the recorded files.
 *
 * Data quality: 66 findings that cycle through every class, status, check and source, so the
 * list has a second "show more" page; confirmed errors carry evidence links.
 * Onset: the 65 PIPC rows, with every status, medians that tie, a median without an interval,
 * a median that only shows same-day heaping, and a row without a median.
 */
import * as D from "@/api/decode";
import {
  CHECKS,
  CLASSES,
  dataQualityReport,
  STATUSES,
  type DataQualityFixture,
  type DataQualityReport,
  type Finding,
} from "@/research/dataQuality";
import {
  CAVEATS,
  ONSET_STATUSES,
  onsetTable,
  type OnsetFixture,
  type OnsetRow,
  type OnsetTable,
} from "@/research/onset";

function checked<T>(decoder: D.Decoder<T>, value: T, what: string): T {
  const r = D.decode(decoder, value);
  if (!r.ok) throw new Error(`synthetic fixture ${what} does not decode`);
  return value;
}

// --- data quality ----------------------------------------------------------------------------

const SOURCES = ["titck", "wikidata", "eu_es_cima", "titck+eu_es_cima"];
const REASONS = [
  "wrong_substance",
  "both_regulators_publish_it",
  "regulators_differ",
];

/** Finding `i` (0-based): class cycles fastest, then status, then source. */
export function finding(i: number, over: Partial<Finding> = {}): Finding {
  const klass = CLASSES[i % 3]!;
  const check =
    klass === "confirmed_error"
      ? CHECKS[0]
      : klass === "benign_difference"
        ? CHECKS[1]
        : CHECKS[2];
  const group = String.fromCharCode(65 + (i % 8)); // A..H
  const code = `${group}0${i % 9}AB0${(i % 8) + 1}`;
  const key = `Q${1000 + i}`;
  return {
    id: `${check}:synthetic:${key}:${code}`,
    status: STATUSES[Math.floor(i / 3) % 3]!,
    class: klass,
    class_changed_from: null,
    check,
    source: SOURCES[i % SOURCES.length]!,
    key,
    label_en: `Synthetic substance ${String(i).padStart(2, "0")}`,
    wikidata_url: `https://www.wikidata.org/wiki/${key}`,
    code,
    compared_codes: [`${group}0${i % 9}AA01`, `C0${i % 9}AA02`],
    products: (i % 4) + 1,
    reasons: [REASONS[i % REASONS.length]!],
    other_keys: [],
    upstream: klass === "confirmed_error" ? "persisting" : null,
    whocc_group_urls: [
      `https://atcddd.fhi.no/atc_ddd_index/?code=${group}0${i % 9}AA&showdescription=no`,
      `https://atcddd.fhi.no/atc_ddd_index/?code=C0${i % 9}AA&showdescription=no`,
    ],
    how_to_find:
      "Search the licensed medicines list of the source for single-ingredient products that carry this code.",
    ...over,
  };
}

export const FINDINGS = 66;

export function dataQualitySet(): DataQualityFixture & {
  report: DataQualityReport;
} {
  const findings = Array.from({ length: FINDINGS }, (_, i) =>
    i === 4
      ? finding(i, { class_changed_from: "needs_pharmacist" })
      : finding(i),
  );
  const count = <K extends string>(
    keys: readonly K[],
    pick: (f: Finding) => K,
  ) =>
    Object.fromEntries(
      keys.map((k) => [k, findings.filter((f) => pick(f) === k).length]),
    ) as Record<K, number>;
  const byClass = count(CLASSES, (f) => f.class);
  const byStatus = count(STATUSES, (f) => f.status);
  const confirmed = findings.filter((f) => f.class === "confirmed_error");
  const report: DataQualityReport = checked(
    dataQualityReport,
    {
      dataset: "janus-data-quality",
      version: "data-quality-test+synthetic",
      run_id: "20260101T000000Z-synthetic",
      run_date: "2026-01-01",
      previous_run_id: null,
      previous_version: null,
      license: "CC BY 4.0",
      license_url: "https://creativecommons.org/licenses/by/4.0/",
      attribution: "Synthetic test data, CC BY 4.0.",
      review_status:
        "Generated by deterministic rules. Expert review has not yet been done.",
      notices: ["no_titck_rows_or_product_names", "not_medical_advice"],
      resolution_dataset: "0".repeat(64),
      sources: {
        wikidata: {
          pipeline: "wikidata_ingredients",
          run_id: "20260101T000000Z-synthetic-wd",
          snapshot_date: "2026-01-01",
          license: "CC0 1.0",
        },
      },
      summary: {
        findings: findings.length,
        by_class: byClass,
        by_status: byStatus,
        confirmed_errors_still_published: confirmed.length,
        confirmed_errors_resolved_upstream: 0,
      },
      findings,
    },
    "data-quality report",
  );
  return {
    recorded: "synthetic",
    report,
    csv: "finding_id,status,class\nsynthetic:1,persisting,confirmed_error\n",
    md: "# Synthetic data-quality report\n",
  };
}

// --- onset -----------------------------------------------------------------------------------

const NO_STATS = {
  median_days: null,
  q25_days: null,
  q75_days: null,
  median_exact_ci_low_days: null,
  median_exact_ci_high_days: null,
  median_exact_ci_coverage: null,
  median_reflects_zero_heaping: null,
  median_days_without_day_one: null,
  median_days_earliest_class_start: null,
  median_days_distinct_date_pairs: null,
  weibull_shape: null,
  weibull_shape_ci_low: null,
  weibull_shape_ci_high: null,
  weibull_shape_class: null,
} satisfies Partial<OnsetRow>;

/** Row at PIPC position `p` (1-65) with the given status and sensible numbers for it. */
export function onsetRowOf(
  p: number,
  status: OnsetRow["status"],
  over: Partial<OnsetRow> = {},
): OnsetRow {
  const stats = status === "described" || status === "small_sample";
  const candidate = status === "no_candidate_reports" ? 0 : 20 + p * 7;
  const withInterval =
    status === "described"
      ? 40 + p
      : status === "small_sample"
        ? 12
        : status === "cluster_dominated"
          ? 30
          : status === "count_only"
            ? 3
            : 0;
  return {
    pipc_position: p,
    pipc_system: "Synthetic system",
    pipc_drug_a: `Synthetic drug class ${p}`,
    pipc_adverse_event: `Synthetic event ${p}`,
    pipc_drug_b: `Synthetic treatment ${p}`,
    pipc_locator: `Table 1, row ${p}`,
    index_class: "synthetic_class",
    event_key: `synthetic_event_${p}`,
    event_pts: [`Synthetic term ${p}`],
    shared_with_positions: [],
    route_groups_counted: ["systemic_or_unknown"],
    candidate_reports: candidate,
    reports_with_interval: withInterval,
    usable_share: candidate ? withInterval / candidate : null,
    candidates_without_interval_by_reason: candidate
      ? { no_therapy_start: candidate - withInterval }
      : {},
    distinct_intervals: Math.min(withInterval, 20),
    event_year_min: withInterval ? 2010 : null,
    event_year_max: withInterval ? 2026 : null,
    status,
    small_sample: status === "small_sample",
    omitted_reason: stats
      ? null
      : "fewer than 10 reports with a usable interval: counts only",
    ...NO_STATS,
    reports_without_day_one: 0,
    sensitivity_omitted_reason: null,
    zero_day_reports: 0,
    zero_day_share: null,
    day_one_reports: 0,
    day_one_share: null,
    largest_date_cluster: withInterval ? 2 : 0,
    shape_omitted_reason: null,
    row_notes: [],
    descriptive_only: true,
    causal: false,
    incidence: false,
    counts_are: "reports",
    ...(stats
      ? {
          median_days: 2 + (p % 5), // several rows tie
          q25_days: 0,
          q75_days: 30,
          median_exact_ci_low_days: 1,
          median_exact_ci_high_days: 9,
          median_exact_ci_coverage: 0.95,
          median_reflects_zero_heaping: false,
          median_days_without_day_one: 2,
          median_days_earliest_class_start: 2,
          median_days_distinct_date_pairs: 2,
          zero_day_reports: 5,
          zero_day_share: 0.2,
        }
      : {}),
    ...(status === "described"
      ? {
          weibull_shape: 0.45,
          weibull_shape_ci_low: 0.4,
          weibull_shape_ci_high: 0.5,
          weibull_shape_class: "early" as const,
        }
      : {}),
    ...over,
  };
}

const PLAN: OnsetRow["status"][] = [
  "described",
  "small_sample",
  "count_only",
  "cluster_dominated",
  "no_interval",
  "described",
  "count_only",
  "small_sample",
];

/** The status of position `p` (every status occurs; positions 63-65 are the odd ones). */
const statusAt = (p: number): OnsetRow["status"] =>
  p === 64 || p === 65 ? "no_candidate_reports" : PLAN[p % PLAN.length]!;

export function onsetSet(): OnsetFixture & { table: OnsetTable } {
  const rows = Array.from({ length: 65 }, (_, i) => {
    const p = i + 1;
    const status = statusAt(p);
    if (p === 6)
      // a median with no exact interval: never shown
      return onsetRowOf(p, status, { median_exact_ci_high_days: null });
    if (p === 11)
      // a median that only shows same-day heaping
      return onsetRowOf(p, "described", {
        median_days: 0,
        median_exact_ci_low_days: 0,
        median_exact_ci_high_days: 0,
        median_reflects_zero_heaping: true,
      });
    return onsetRowOf(p, status);
  });
  const byStatus = Object.fromEntries(
    ONSET_STATUSES.map((s) => [s, rows.filter((r) => r.status === s).length]),
  );
  const table: OnsetTable = checked(
    onsetTable,
    {
      dataset: "janus-faers-onset-pipc",
      version: "faers-onset-test+synthetic",
      built_at: "2026-01-01T00:00:00+00:00",
      faers_receipt_quarters: ["2025Q4", "2026Q1"],
      faers_snapshot_date: "2026-01-01",
      license: "CC BY 4.0",
      attribution: "Synthetic test data, CC BY 4.0.",
      meddra_notice: "Synthetic notice: event terms are test labels.",
      review_status: "Generated by deterministic rules. Not reviewed.",
      descriptive_only: true,
      causal: false,
      incidence: false,
      counts_are: "reports",
      caveats: Object.fromEntries(
        CAVEATS.map((c) => [c, `Synthetic English text of the ${c} caveat.`]),
      ),
      summary: {
        rows: rows.length,
        rows_with_median: rows.filter((r) => r.median_days !== null).length,
        by_status: byStatus,
      },
      rows,
    },
    "onset table",
  );
  return {
    recorded: "synthetic",
    table,
    csv: "pipc_position,status\n1,described\n",
  };
}

/** The first position with a status. */
export const firstRowWith = (t: OnsetTable, status: OnsetRow["status"]) =>
  t.rows.find((r) => r.status === status)!.pipc_position;

/** Whether a row's median can be compared in a sort (shown, and not only same-day heaping). */
export const comparableMedian = (r: OnsetRow): boolean =>
  (r.status === "described" || r.status === "small_sample") &&
  r.median_days !== null &&
  r.median_exact_ci_low_days !== null &&
  r.median_exact_ci_high_days !== null &&
  !r.median_reflects_zero_heaping;
